function saltFormula(cat,an){const c=ION[cat],a=ION[an];const g=(x,y)=>y?g(y,x%y):x;const l=Math.abs(c.z*a.z)/g(Math.abs(c.z),Math.abs(a.z));const nc=l/c.z,na=l/Math.abs(a.z);
 const part=(io,n)=>n===1?io.f:(io.poly&&!io.f.startsWith("[")?"("+io.f+")"+n:io.f+n);return a.org?part(a,na)+part(c,nc):part(c,nc)+part(a,na)}

